import data from "./story-data.json";

/** Arrays behind the research and training scenes, generated by frontend/scripts/story_data.py and re-checked by
 *  facts.sources.test.ts against the tracked overlap CSV and (when present) the served artifact. */
export type CopyClip = { clip: string; group: string; className: string; offset: number; seconds: number; ncc: number };
export type TrainingCurve = {
  seed: number; epochs: number; restoredEpoch: number;
  accuracy: number[]; valAccuracy: number[]; loss: number[]; valLoss: number[]; source: string;
};

export const STORY_DATA = data as {
  nccHistogram: { binWidth: number; counts: number[]; source: string };
  oneRecording: { reference: string; patient: string; clips: CopyClip[]; source: string };
  trainingCurve: TrainingCurve | null;
};
